// Poll the EDGAR submissions index for each watched company and emit
// the 8-K filings from the last few days as monitored-event objects.
// Self-contained (no paired items): carries cik through the same closure.
const userAgent = $env.EDGAR_USER_AGENT || 'ledgerlens monitoring zzlawlzz5@gmail.com';

// --- edit here: the watchlist (10-digit CIKs) and the lookback window ---
const watchlist = [
  { cik: '0000320193', ticker: 'AAPL' },
  { cik: '0000789019', ticker: 'MSFT' },
  { cik: '0001045810', ticker: 'NVDA' },
];
const lookbackDays = 3;
// -----------------------------------------------------------------------

const cutoff = new Date(Date.now() - lookbackDays * 864e5);
const events = [];
for (const { cik } of watchlist) {
  const url = `https://data.sec.gov/submissions/CIK${cik}.json`;
  let data;
  try {
    data = await this.helpers.httpRequest({ url, headers: { 'User-Agent': userAgent }, json: true });
  } catch (e) {
    continue; // a single company being unreachable must not drop the whole tick
  }
  const recent = (data.filings && data.filings.recent) || {};
  const forms = recent.form || [];
  for (let i = 0; i < forms.length; i++) {
    if (forms[i] !== '8-K') continue;
    const filed = new Date(recent.filingDate[i]);
    if (isNaN(filed.getTime()) || filed < cutoff) continue;
    const accession = recent.accessionNumber[i];
    const primaryDocument = recent.primaryDocument[i];
    const accNoDash = String(accession).replace(/-/g, '');
    const sourceUrl = `https://www.sec.gov/Archives/edgar/data/${parseInt(cik, 10)}/${accNoDash}/${primaryDocument}`;
    events.push({
      source: 'edgar',
      external_id: accession,
      event_type: '8-K',
      company_external_id: cik,
      occurred_at: filed.toISOString(),
      source_url: sourceUrl,
      payload: { cik, accession, primary_document: primaryDocument, form: '8-K' },
    });
  }
}
return [{ json: { events } }];

// The ingest endpoint returns only the genuinely new events (deduped by
// UNIQUE(source, external_id)). Fan them out, one item per new event, so the
// summarize node runs once per new filing.
const resp = $input.first().json || {};
const newIds = resp.new || [];
return newIds.map((id) => ({ json: { source: 'edgar', external_id: id } }));
